<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {money,time,confirm} from '../../utils/format';const catalog=ref<any>({plans:[],benefits:[]}),member=ref<any>(null),health=ref<any>({}),purchase=ref<any>(null);const {loading,error,load,busy,action}=usePage(async()=>{const [c,m,h]=await Promise.all([request('/public/catalog'),request('/membership/mine'),request('/public/health')]);catalog.value=c;member.value=m[0];health.value=h});async function buy(p:any){if(!await confirm('确认选择 '+(p.display_name||p.name)+'，价格 '+money(p.price)+'？'))return;purchase.value={id:await request('/membership/purchases','POST',{planId:p.id}),amount:p.price}}async function pay(){await request('/membership/purchases/'+purchase.value.id+'/demo-pay','POST');purchase.value=null;await load()}
</script><template><PageShell title="暖爪会员" back :loading="loading" :error="error" @retry="load"><view class="dark-card"><text class="eyebrow" style="color:#d6b89e">WARM PAW CLUB</text><view style="font-size:28px;margin:14px 0">让陪伴，长久一点。</view><text class="muted">{{member?.status==='ACTIVE'?'会员有效期至 '+time(member.expires_at):'为经常需要照顾的毛孩子，准备一份长期安心。'}}</text><view v-if="member" style="margin-top:16px">累计节省 {{money(member.saved_amount)}}</view></view><view class="section">专属权益</view><view class="grid"><view v-for="b in catalog.benefits" :key="b.id" class="tile"><view class="tile-icon">✦</view><view>{{b.name}}</view><text class="muted">{{b.description}}</text></view></view><view class="section">选择适合你的陪伴计划</view><view v-for="p in catalog.plans" :key="p.id" class="card"><view class="row"><view><view style="font-weight:700">{{p.display_name||p.name}}</view><text class="muted">{{p.months}} 个月</text></view><text class="amount">{{money(p.price)}}</text></view><button class="secondary" style="margin-top:16px" :disabled="busy||!!purchase" @click="action(()=>buy(p),'购买单已创建')">{{member?'续费':'开通'}}会员</button></view><view v-if="purchase" class="card"><view>购买单已创建 · {{money(purchase.amount||purchase.price)}}</view><view class="notice warning">{{health.demoPaymentsEnabled?'本地演示支付，不产生真实扣款':'微信支付尚未配置，暂不能完成付款'}}</view><button v-if="health.demoPaymentsEnabled" class="primary" :disabled="busy" @click="action(pay,'会员已开通')">演示支付并开通</button></view></PageShell></template>

